import{_ as i,l as o,o as e,c as l,v as t,p as s,x as r,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"5NF 与反规范化","description":"","frontmatter":{"title":"5NF 与反规范化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/5nf-denormalization.md","filePath":"cs/5nf-denormalization.md","lastUpdated":1789023840000}'),F={name:"cs/5nf-denormalization.md"};function h(N,a,_,c,m,A){const n=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="_5nf-与反规范化" tabindex="-1">5NF 与反规范化 <a class="header-anchor" href="#_5nf-与反规范化" aria-label="Permalink to &quot;5NF 与反规范化&quot;">​</a></h1><div class="epigraph"><p>5NF 要求凡是无损的 n 路投影分解，其连接依赖都由候选键蕴含。反规范化则故意留下冗余，用完整性预算换少连接。</p><footer>—— 据 Fagin, Normal Forms and Relational Database Operators, SIGMOD 1979；Date；Ramakrishnan and Gehrke</footer></div><p><a href="/cs/mvd-4nf">上一课</a>沿独立多值拆表。本课不重定义 MVD。缺口有两向：更细的连接依赖（JD）与 5NF；以及工程上反向走的反规范化。依赖理论单元在此封口，优化器单元从 Selinger 再开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有的关系 4NF 已过，仍存在：它等于三个投影的连接，但任两路连接都不够——必须三路才无损。这是连接依赖 \\(* (X,Y,Z)\\)。5NF（投影-连接范式，PJ/NF）：每个 JD 都被候选键所蕴含（分解平凡）。实践中真正常见的是供应商–零件–项目一类约束，比 4NF 稀。</p><p>反规范化：故意保留违反 3NF/BCNF 的列（如订单行上重复顾客名），减少查询连接。缺口是把这写成<strong>显式合同</strong>：哪条 FD 不再由模式保证，改由应用、触发器或物化维护。不是「为了性能可以随便宽表」。</p><p><span class="marginnote">Fagin 1979。Date 强调 5NF 与「只按键连接」的直觉。物化视图是受控反规范化：有定义查询，维护规则可分析。宽表缓存若无定义，只是副本漂移。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>5NF 设计：若业务约束确实是三路可拼且两路不可，则拆成三张「键对」表。否则不要为理论而拆。反规范化：量连接代价与更新异常频率；冗余列随源列更新必须同步——触发器课的过程或后课物化刷新。</p><p>从 5NF 表再连回宽结果，是查询或视图，不是把基表重新加宽。OLAP 星型模式后课会系统性地反规范化维表；本课只给原则。</p>',10)),(e(),s(E,null,{default:r(()=>[p(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20JD%5B%22%E8%BF%9E%E6%8E%A5%E4%BE%9D%E8%B5%96%22%5D%20--%3E%20F5%5B%225NF%3A%20%E7%94%B1%E9%94%AE%E8%95%B4%E5%90%AB%22%5D%0A%20%20F5%20--%3E%20SPLIT%5B%22%E5%A4%9A%E8%B7%AF%E6%8A%95%E5%BD%B1%E8%A1%A8%22%5D%0A%20%20DEN%5B%22%E5%8F%8D%E8%A7%84%E8%8C%83%E5%8C%96%22%5D%20--%3E%20RED%5B%22%E5%8F%97%E6%8E%A7%E5%86%97%E4%BD%99%22%5D%0A%20%20RED%20--%3E%20MAINT%5B%22%E8%A7%A6%E5%8F%91%E5%99%A8%20%2F%20%E7%89%A9%E5%8C%96%20%2F%20%E5%BA%94%E7%94%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>无损分解的终点：5NF 说「没有额外的无损切法」。再拆只会增加连接、不消除由 JD 造成的异常。反规范化增加更新异常风险，换的是读路径上的连接与随机 I/O——代价模型在优化器单元量化，本课只定性。</p><p>与 ORM：宽对象常诱使反规范化；阻抗课已警告导航不是计划。冗余字段会让 N+1 看起来「少连表」，更新却更脆。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 DKNF 等更强范式写入必做。也不开始 Selinger 搜索。域-键范式点名存在：约束若都能收成域与键，则理论漂亮，现实 CHECK 与触发器仍在。</p><p>后课默认：模式先按 3NF/BCNF/需要时 4NF 设计；5NF 仅当真正有多路 JD；冗余必须有维护者。优化器单元第一课：给定模式，如何搜连接顺序。</p><p>依赖理论补的是主干范式课的推导与 4NF/5NF；不是重开关系模型第一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>5NF 处理非平凡连接依赖，比 4NF 更稀。</li><li>反规范化是显式冗余加维护，不是忘了分解。</li><li>下一单元 Selinger 动态规划：在合法计划空间里搜代价。</li><li>出处：Fagin 1979；Date；Ramakrishnan and Gehrke。</li></ul>',9))])}const u=i(F,[["render",h]]);export{f as __pageData,u as default};
